        nega
        adda    #$15
        staa    >LoopTimeLast
        cmpa    >LoopTimeWorst
        bls     L92BA
        staa    >LoopTimeWorst
L92BA:
        ldaa    >MinimumTimerCountBeforeMainloopCanContinue
SetupMainLoopCounter:
        addb    #$15
        stab    >MinimumTimerCountBeforeMainloopCanContinue
L92C2:
